INSERT INTO `tb_recommended_book` VALUES (1, '地球之肺与人类未来\r\n', '这本书深入探讨了森林对地球生态系统的重要性，以及人类如何通过保护森林来应对气候变化。', 'https://q-gallery.oss-cn-guangzhou.aliyuncs.com/img/202411242348553.png', '约翰·里德', '美国', NULL, '2024-11-24 23:49:32', '2024-11-24 23:49:34');
INSERT INTO `tb_recommended_book` VALUES (2, '师与先知：两种环保科学观如何帮助人类应对生态危机', '这本书通过对比两种不同的环保科学观，探讨了如何在科技和自然之间找到平衡，以应对日益严峻的生态危机。', 'https://q-gallery.oss-cn-guangzhou.aliyuncs.com/img/202411242350450.png', '查尔斯·C. 曼恩著', '美国', NULL, '2024-11-24 23:50:37', '2024-11-24 23:50:40');
INSERT INTO `tb_recommended_book` VALUES (3, '海的边缘', '这本书通过对海洋生态系统的详细描写，揭示了人类活动对海洋环境的影响，呼吁人们采取行动保护海洋。', 'https://q-gallery.oss-cn-guangzhou.aliyuncs.com/img/202411242351686.png', '蕾切尔·卡森', '美国', NULL, '2024-11-24 23:51:12', '2024-11-24 23:51:15');
INSERT INTO `tb_recommended_book` VALUES (4, '绿色使命', '本书强调了应对气候变化的责任问题，作者呼吁石油和天然气公司承担起其在气候问题中不可推卸的责任，并考虑了不同石油公司所处的环境和背景，并根据其行为制定了不同的赔偿和去碳化标准。通过研究责任和义务的政策内涵，本书强调了社会、经济等因素在应对气候变化中的重要性，并呼吁国家采取积极措施引导企业转向低碳发展。', 'https://q-gallery.oss-cn-guangzhou.aliyuncs.com/img/202411262242232.png', '马尔科·格拉索', '意大利', NULL, '2024-11-26 22:46:50', '2024-11-26 22:46:53');
INSERT INTO `tb_recommended_book` VALUES (5, '数碳经济', '绿色发展是以效率、和谐、持续为目标的经济增长和社会发展方式。自工业革命以来，大国崛起的代价是经济迅猛发展必然带来的环境污染。继创造举世瞩目的经济增长奇迹后，新时代的中国作出了新的选择。', 'https://q-gallery.oss-cn-guangzhou.aliyuncs.com/img/202411262248124.png', '人民论坛', '中国', NULL, '2024-11-26 22:48:29', '2024-11-26 22:48:33');
INSERT INTO `user_deal` VALUES (1, '油电混动自行车', '来跟我换吧', '金条', '自行车', '1', 1, '2025-01-17 16:34:04', '2025-01-17 16:34:04');
INSERT INTO `user_deal_good_img` VALUES (1, 1, 'https://img14.360buyimg.com/n1/jfs/t1/216642/33/49478/76614/67432744F9042bf07/77530d9c811094d4.jpg', '2025-02-13 17:53:54', '2025-02-13 17:53:58', 0);
INSERT INTO `user_feedback` VALUES (1, 1, '59605904@qq.com', NULL, '测试1', '这是反馈的内容，测试。', 0, '2024-11-17 20:39:05', '2024-11-17 20:37:12');
INSERT INTO `user_feedback` VALUES (2, 1, '59605904@qq.com', NULL, 'string', 'string', 0, '2024-11-19 09:10:30', '2024-11-19 09:10:30');
INSERT INTO `user_feedback` VALUES (3, 71, 'jialun1@icloud.com', '14505752003', 'rpple', 'Import Wizard allows you to import data to tables/collections from CSV, TXT, XML, DBF and more. How we spend our days is, of course, how we spend our lives.', 0, '2024-10-12 00:36:57', '2024-11-24 07:53:12');
INSERT INTO `user_feedback` VALUES (4, 82, 'fu104@mail.com', '17888691494', 'Orcnge', 'A query is used to extract data from the database in a readable format according to the user\'s request. Instead of wondering when your next vacation is, maybe you should set up a life you don’t need to escape from.', 0, '2024-10-08 04:46:52', '2024-11-24 01:59:54');
INSERT INTO `user_feedback` VALUES (5, 39, 'htlai@mail.com', '14929191121', 'Cherry', 'Champions keep playing until they get it right. To successfully establish a new connection to local/remote server - no matter via SSL or SSH, set the database login information in the General tab. Navicat provides a wide range advanced features, such as compelling code editing capabilities,         ', 0, '2024-10-24 00:51:10', '2024-11-24 10:47:47');
INSERT INTO `user_feedback` VALUES (6, 66, 'kakar9@outlook.com', '14217008642', 'Raspberry', 'All the Navicat Cloud objects are located under different projects. You can share the project to other Navicat Cloud accounts for collaboration.', 0, '2024-10-06 15:29:41', '2024-11-24 09:13:00');
INSERT INTO `user_feedback` VALUES (7, 74, 'xiziy@gmail.com', '14724882386', 'Grape', 'There is no way to happiness. Happiness is the way. Navicat authorizes you to make connection to remote servers running on different platforms (i.e. Windows, macOS, Linux and UNIX), and supports PAM and GSSAPI authentication.', 0, '2024-11-11 09:52:17', '2024-11-24 12:56:12');
INSERT INTO `user_feedback` VALUES (8, 1, 'kono906@outlook.com', '15343022103', 'Raspberry plus', 'What you get by achieving your goals is not as important as what you become by achieving your goals. You cannot save people, you can just love them.', 0, '2024-11-03 23:51:34', '2024-11-24 07:16:45');
INSERT INTO `user_feedback` VALUES (9, 96, 'ueda6@gmail.com', '15355999668', 'Apwle mini', 'A man’s best friends are his ten fingers. The Main Window consists of several toolbars and panes for you to work on connections, database objects and advanced tools. I destroy my enemies when I make them my friends. Navicat allows you to transfer data from one database and/or schema               ', 1, '2024-11-03 18:11:41', '2024-11-24 02:13:04');
INSERT INTO `user_feedback` VALUES (10, 85, 'coleman2@outlook.com', '15989173519', 'omni-Apple', 'To successfully establish a new connection to local/remote server - no matter via SSL or SSH, set the database login information in the General tab. You must be the change you wish to see in the world. Optimism is the one quality more associated with success and happiness than any other.', 1, '2024-11-07 17:43:00', '2024-11-24 06:51:22');
INSERT INTO `user_feedback` VALUES (11, 7, 'sasam@outlook.com', '13090735745', 'Rambutan', 'In the middle of winter I at last discovered that there was in me an invincible summer.', 0, '2024-10-27 14:15:28', '2024-11-24 07:12:22');
INSERT INTO `user_feedback` VALUES (12, 20, 'tanght@hotmail.com', '14620707854', 'Grape', 'Navicat allows you to transfer data from one database and/or schema to another with detailed analytical process. You cannot save people, you can just love them. If you wait, all that happens is you get older. Navicat Monitor is a safe, simple and agentless remote server monitoring                   ', -1, '2024-10-24 18:40:51', '2024-11-24 22:39:29');
INSERT INTO `user_feedback` VALUES (13, 65, 'aoshimaruy67@icloud.com', '14634990195', 'Rambutan air', 'Navicat Monitor requires a repository to store alerts and metrics for historical analysis.', 0, '2024-11-12 20:41:35', '2024-11-24 17:36:44');
INSERT INTO `user_feedback` VALUES (14, 99, 'zhiyuanl622@hotmail.com', '14141318370', 'Mawgo', 'To start working with your server in Navicat, you should first establish a connection or several connections using the Connection window. Navicat provides a wide range advanced features, such as compelling code editing capabilities, smart code-completion, SQL formatting, and more.', 0, '2024-11-10 14:02:38', '2024-11-24 18:40:40');
